-- Remove a conta temporária usada só para enviar as fotos (não é de ninguém).
delete from auth.users where id = 'd0000000-0000-4000-8000-0000000000bb' and email = 'temp-upload@julianaprado.app';

-- Conferência: deve listar 8 posts "aprovado", cada um com a sua peça.
select p.titulo, pr.nome as peca, p.status from public.posts p left join public.produtos pr on pr.id = p.produto_id order by p.publicado_em desc;
